      // --- NOVAS: Frases de Motivação ---
      'mot_01': "You are capable of incredible things. Respect your time.",
      'mot_02': "Every small progress is great progress.",
      'mot_03': "It's okay not to be okay all the time. Be kind to yourself.",
      'mot_04': "Your unique perceptions of the world are a strength.",
      'mot_05': "Breathe deeply. You can handle this.",
      'mot_06': "It is the dream that carries us forward. If we follow reason, we stay quiet, settled. (Ariano Suassuna)",
      'mot_07': "Don't compare yourself to others. Your journey is unique.",
      'mot_08': "Failure is just the opportunity to begin again more intelligently. (Henry Ford)",
