      'mot_15': "Life is 10% what happens to us and 90% how we react to it. – Charles R. Swindoll",
      'mot_16': "Courage is not the absence of fear, but the decision that something else is more important. – Ambrose Redmoon",
      'mot_17': "Don't wait for opportunities, create them. – George Bernard Shaw",
      'mot_18': "Success is the sum of small efforts repeated day in and day out. – Robert Collier",
      'mot_19': "Believe in yourself and all that you are. – Elayne Boosler",
      'mot_20': "Everything you've ever wanted is on the other side of fear. – George Addair",
      'mot_21': "You are stronger than you know.",
      'mot_22': "Do what you can, with what you have. – Theodore Roosevelt",
      'mot_23': "Great things never come from comfort zones. – Roy T. Bennett",
      'mot_24': "Persistence is the path to success. – Charles Chaplin",
      'mot_25': "The only way to do great work is to love what you do. – Steve Jobs",
      'mot_26': "The future belongs to those who believe in the beauty of their dreams. – Eleanor Roosevelt",
      'mot_27': "The journey of a thousand miles begins with a single step. – Lao Tzu",
      'mot_28': "Believe you can and you're halfway there. – Theodore Roosevelt",
      'mot_29': "The only place where success comes before work is in the dictionary. – Vidal Sassoon",
      'mot_30': "It does not matter how slowly you go as long as you do not stop. – Confucius",
      'mot_31': "Life is about creating impact, not an income. – Kevin Kruse",
      'mot_32': "Be the change you wish to see in the world. – Mahatma Gandhi",
      'mot_33': "The best is yet to come. – Anonymous",
      'mot_34': "You are enough just as you are. – Meghan Markle",
      'mot_35': "Believe in the power of your dreams. – Eleanor Roosevelt",
      'mot_36': "Success is not final, failure is not fatal: it is the courage to continue that counts. – Winston Churchill",
      'mot_37': "You should treat your energy as if it were expensive, like a luxury item. Not everyone can have it. What you spend your energy on can be the reason your day is ruined. - Taylor Swift",
      'mot_38': "If we express gratitude for what we have, we will have more to express gratitude for.",
      'mot_39': "There is only happiness if we demand nothing of tomorrow and accept from today, with gratitude, whatever it brings. The magic hour always comes. - Hermann Hesse",
      'mot_40': "Gratitude is the memory of the heart. - Lao Tzu",
      'mot_41': "Gratitude turns what we have into enough. - Melody Beattie",
      'mot_42': "Gratitude is the key to happiness. - Anonymous",
      'mot_43': "Gratitude opens the door to the power, wisdom, and creativity of the universe. - Deepak Chopra",
      'mot_44': "Gratitude is the antidote to resentment and envy. - Anonymous",
      'mot_45': "Gratitude is the foundation of a full and happy life. - Anonymous",
      'mot_46': "Gratitude is the art of painting life with vibrant colors. - Anonymous",
      'mot_47': "Fight with determination, embrace life with passion, lose with class, and win with boldness, because the world belongs to those who dare and life is too much to be insignificant. - Augusto Branco",
      'mot_48': "We are like the weather: made of rainy days and sunny days!",
      'mot_49': "Vitality is shown not only by persistence but by the ability to start over. - F. Scott Fitzgerald",
      'mot_50': "Life isn't about waiting for the storm to pass, but learning to dance in the rain. - Vivian Greene",
      'mot_51': "One can only achieve great success when one remains true to oneself. - Friedrich Nietzsche",
      'mot_52': "When everything seems impossible, it's a sign that you need a few good days of rest to relieve the pressure and clear your mind. Afterward, you'll see that the problems weren't even that big.",
      'mot_53': "Don't torture yourself when things don't go as you planned. Plans help us map the path, but it's normal to have to change them later!",
      'mot_54': "Strength does not come from physical capacity. It comes from an indomitable will. - Mahatma Gandhi",
      'mot_55': "Start by doing what's necessary, then what's possible, and suddenly you are doing the impossible. - St. Francis of Assisi",
      'mot_56': "There is no need to walk fast. Just keep walking.",
