      'mot_58': "Complicated days are part of life. The good thing is that they pass and then good days appear.",
      'mot_59': "Life is like a mountain: it has ups and downs, requires walking, and has landscapes to observe along the way.",
      'mot_60': "Respect your body and treat your mind with care. They are your greatest allies on life's journey.",

      // --- NOVAS: Versículos Bíblicos ---
      'bib_01': "I can do all things through him who strengthens me. (Philippians 4:13)",
      'bib_02': "The Lord is my shepherd; I shall not want. (Psalm 23:1)",
      'bib_03': "Fear not, for I am with you; be not dismayed, for I am your God; I will strengthen you, I will help you. (Isaiah 41:10)",
      'bib_04': "Come to me, all who labor and are heavy laden, and I will give you rest. (Matthew 11:28)",
      'bib_05': "Peace I leave with you; my peace I give to you. Not as the world gives do I give to you. Let not your hearts be troubled, neither let them be afraid. (John 14:27)",
      'bib_06': "The Lord is near to the brokenhearted and saves the crushed in spirit. (Psalm 34:18)",
      'bib_07': "Casting all your anxieties on him, because he cares for you. (1 Peter 5:7)",
      'bib_08': "God is our refuge and strength, a very present help in trouble. (Psalm 46:1)",
      'bib_09': "Weeping may tarry for a night, but joy comes with the morning. (Psalm 30:5b)",
      'bib_10': "For nothing will be impossible with God. (Luke 1:37)",
      'bib_11': "Blessed be the God and Father of our Lord Jesus Christ, the Father of mercies and God of all comfort. (2 Corinthians 1:3)",
      'bib_12': "Be strong, and let your heart take courage, all you who wait for the Lord! (Psalm 31:24)",
      'bib_13': "The Lord is good, a stronghold in the day of trouble; he knows those who take refuge in him. (Nahum 1:7)",
      'bib_14': "But they who wait for the Lord shall renew their strength; they shall mount up with wings like eagles; they shall run and not be weary; they shall walk and not faint. (Isaiah 40:31)",
      'bib_15': "Trust in the Lord with all your heart, and do not lean on your own understanding. (Proverbs 3:5)",
      'bib_16': "The Lord is my light and my salvation; whom shall I fear? (Psalm 27:1)",
      'bib_17': "Commit your way to the Lord; trust in him, and he will act. (Psalm 37:5)",
      'bib_18': "For I know the plans I have for you, declares the Lord, plans for welfare and not for evil, to give you a future and a hope. (Jeremiah 29:11)",
      'bib_19': "Call to me and I will answer you, and will tell you great and hidden things that you have not known. (Jeremiah 33:3)",
      'bib_20': "The Lord is my strength and my song; he has become my salvation. (Psalm 118:14)",
      'bib_21': "For God gave us a spirit not of fear but of power and love and self-control. – 2 Timothy 1:7",
      'bib_22': "Fear not, for I am with you; be not dismayed, for I am your God. – Isaiah 41:10",
      'bib_23': "Blessed are those who hunger and thirst for righteousness, for they shall be satisfied. – Matthew 5:6",
      'bib_24': "Do not be anxious about anything, but in everything by prayer and supplication with thanksgiving let your requests be made known to God. And the peace of God, which surpasses all understanding, will guard your hearts and your minds in Christ Jesus. Finally, brothers, whatever is true, whatever is honorable, whatever is just, whatever is pure, whatever is lovely, whatever is commendable, if there is any excellence, if there is anything worthy of praise, think about these things. Philippians 4:6-8",
      'bib_25': "Cast all your anxiety on him because he cares for you. 1 Peter 5:7",
      'bib_26': "Therefore do not be anxious, saying, 'What shall we eat?' or 'What shall we drink?' or 'What shall we wear?' For the Gentiles seek after all these things, and your heavenly Father knows that you need them all. But seek first the kingdom of God and his righteousness, and all these things will be added to you. Therefore do not be anxious about tomorrow, for tomorrow will be anxious for itself. Sufficient for the day is its own trouble. Matthew 6:31-34",
      'bib_27': "Come to me, all who labor and are heavy laden, and I will give you rest. Take my yoke upon you, and learn from me, for I am gentle and lowly in heart, and you will find rest for your souls. For my yoke is easy, and my burden is light. Matthew 11:28-30",
