      // --- Novas chaves de Expressões ---
      'exp_head_clouds_term': "Estar com a cabeça nas nuvens",
      'exp_head_clouds_meaning': "Estar distraído, desatento ou sonhando acordado.",
      'exp_head_clouds_example': "Ele não ouviu nada, estava com a cabeça nas nuvens.",
      'exp_rain_wet_term': "Chover no molhado",
      'exp_rain_wet_meaning': "Falar ou fazer algo que é óbvio ou repetitivo, que não muda nada.",
      'exp_rain_wet_example': "Explicar isso de novo é chover no molhado.",
      'exp_cost_eyes_term': "Custar os olhos da cara",
      'exp_cost_eyes_meaning': "Ser extremamente caro.",
      'exp_cost_eyes_example': "Aquele celular novo custou os olhos da cara.",
      'exp_ace_it_term': "Tirar de letra",
      'exp_ace_it_meaning': "Fazer algo com extrema facilidade.",
      'exp_ace_it_example': "Ele estudou muito e tirou a prova de letra.",
      'exp_troll_term': "Trollar",
      'exp_troll_meaning': "(Gíria da internet) Provocar ou enganar alguém por diversão.",
      'exp_troll_example': "O amigo dele o 'trollou' fingindo que tinha esquecido seu aniversário.",
      'exp_cringe_term': "Cringe",
      'exp_cringe_meaning': "(Gíria da internet) Algo que causa vergonha alheia ou constrangimento.",
      'exp_cringe_example': "A dança que ele fez na festa foi muito cringe.",
      'exp_cookie_seeker_term': "Biscoiteiro(a)",
      'exp_cookie_seeker_meaning': "(Gíria da internet) Alguém que faz postagens para chamar a atenção e ganhar 'biscoitos' (curtidas/elogios).",
      'exp_cookie_seeker_example': "Ele postou aquela foto só para ganhar biscoito.",
      'exp_be_cool_term': "Ficar de boa",
      'exp_be_cool_meaning': "Estar calmo, relaxado, sem problemas.",
      'exp_be_cool_example': "Não se preocupe, estou de boa.",
      'exp_go_overboard_term': "Meter o pé na jaca",
      'exp_go_overboard_meaning': "Exagerar, cometer excessos (especialmente em comida, bebida ou festa).",
      'exp_go_overboard_example': "No fim de semana, ele meteu o pé na jaca e comeu três fatias de bolo.",
      'exp_take_the_blame_term': "Pagar o pato",
      'exp_take_the_blame_meaning': "Levar a culpa por algo que não fez ou ser o único a sofrer as consequências.",
      'exp_take_the_blame_example': "O time todo jogou mal, mas só o goleiro pagou o pato pela derrota.",
      'exp_swallow_frog_term': "Engolir sapo",
      'exp_swallow_frog_meaning': "Ter que aceitar ou ouvir algo desagradável sem poder reclamar.",
      'exp_swallow_frog_example': "Tive que engolir sapo na reunião para não arrumar briga.",
      'exp_get_pissed_term': "Ficar pistola",
      'exp_get_pissed_meaning': "(Gíria) Ficar muito bravo, irritado.",
      'exp_get_pissed_example': "Ele ficou pistola porque o computador travou no meio do trabalho.",
      'exp_go_wrong_term': "Dar B.O.",
      'exp_go_wrong_meaning': "(Gíria) Dar problema, dar errado.",
      'exp_go_wrong_example': "A impressora parou de funcionar, vai dar B.O. com o chefe.",
      'exp_be_real_term': "Mandar a real",
      'exp_be_real_meaning': "(Gíria) Falar a verdade, ser direto e sincero.",
      'exp_be_real_example': "Vou mandar a real para ele: a ideia não é boa.",
      'exp_no_time_brother_term': "Sem tempo, irmão",
      'exp_no_time_brother_meaning': "(Gíria) Expressão usada para dizer que não tem paciência ou tempo para algo.",
      'exp_no_time_brother_example': "Ele veio com desculpas, mas eu 'tô sem tempo, irmão.",
      'exp_crush_term': "Crush",
      'exp_crush_meaning': "(Gíria) Pessoa por quem se tem uma atração ou interesse romântico.",
      'exp_crush_example': "Meu crush me mandou uma mensagem hoje!",
      'exp_ship_term': "Shipar",
      'exp_ship_meaning': "(Gíria da internet) Torcer para que duas pessoas formem um casal.",
      'exp_ship_example': "Eu 'shipo' muito aqueles dois personagens da série.",
      'exp_flop_term': "Flopar",
      'exp_flop_meaning': "(Gíria da internet) Fracassar, não ter o sucesso esperado.",
      'exp_flop_example': "A festa que ele organizou 'flopou', quase ninguém foi.",
      'exp_slay_term': "Lacrar",
      'exp_slay_meaning': "(Gíria da internet) Fazer algo de forma impressionante ou definitiva, geralmente em debates ou discussões online.",
