      'exp_make_fool_example': "Ela pagou mico ao esquecer o nome do colega durante a apresentação.",
      'exp_walk_eggshells_term': "Pisar em ovos",
      'exp_walk_eggshells_meaning': "Agir com muito cuidado para evitar problemas ou ofender alguém.",
      'exp_walk_eggshells_example': "Ele estava pisando em ovos durante a reunião com o chefe.",
      'exp_keep_eye_on_term': "Ficar de olho",
      'exp_keep_eye_on_meaning': "Observar atentamente algo ou alguém.",
      'exp_keep_eye_on_example': "Vou ficar de olho nas promoções da loja.",
      'exp_take_break_term': "Dar um tempo",
      'exp_take_break_meaning': "Fazer uma pausa ou intervalo em uma atividade ou relacionamento.",
      'exp_take_break_example': "Eles decidiram dar um tempo no relacionamento para pensar.",
      'exp_be_chill_term': "Ficar na boa",
      'exp_be_chill_meaning': "Estar em paz, sem preocupações ou conflitos.",
      'exp_be_chill_example': "Depois de resolver os problemas, ele está ficando na boa.",
      'exp_jump_gun_term': "Queimar a largada",
      'exp_jump_gun_meaning': "Agir precipitadamente ou começar algo antes do tempo adequado.",
      'exp_jump_gun_example': "Ele queimou a largada ao anunciar o projeto antes de ter tudo pronto.",
      'exp_give_it_gas_term': "Dar um gás",
      'exp_give_it_gas_meaning': "Aumentar o esforço ou a intensidade em uma atividade.",
      'exp_give_it_gas_example': "Ele deu um gás nos estudos para passar no vestibular.",
      'exp_cry_spilled_milk_term': "Não adianta chorar pelo leite derramado",
      'exp_cry_spilled_milk_meaning': "Não faz sentido lamentar algo que já aconteceu e não pode ser mudado.",
      'exp_cry_spilled_milk_example': "Você perdeu o prazo, não adianta chorar pelo leite derramado.",
      'exp_want_it_easy_term': "Quer moleza? Então senta no pudim",
      'exp_want_it_easy_meaning': "É uma maneira de dizer que a pessoa deve lidar com as dificuldades da vida, pois não haverá atalhos nem 'moleza'.",
      'exp_want_it_easy_example': "Se você quer entrar nessa competição, quer moleza? Então senta no pudim.",
      'exp_went_bad_term': "Deu ruim",
      'exp_went_bad_meaning': "(Gíria) Algo deu errado ou não saiu como planejado.",
      'exp_went_bad_example': "Tentei consertar o carro, mas deu ruim e agora está pior.",
      'exp_do_nothing_term': "Ficar de bobeira",
