      'cha_c_15_step1': "Escolha uma frase simples, como 'O que você está fazendo aqui?'.",
      'cha_c_15_step2': "Pratique dizê-la em voz alta com diferentes emoções.",
      'cha_c_15_step3': "1. Com raiva. 2. Com surpresa genuína. 3. Com curiosidade. 4. Com medo.",
      'cha_c_15_step4': "Note como sua entonação, volume e velocidade mudam.",
      'cha_c_15_extra': "Pode gravar sua voz no celular para ouvir a diferença.",
      'cha_c_16_title': "O Silêncio Confortável",
      'cha_c_16_obj': "Aprender a não preencher todo silêncio em uma conversa.",
      'cha_c_16_step1': "Quando uma pausa natural ocorrer em uma conversa com alguém confortável (amigo, família).",
      'cha_c_16_step2': "Resista ao impulso de preenchê-la imediatamente.",
      'cha_c_16_step3': "Apenas mantenha uma expressão neutra e relaxada. Deixe a outra pessoa falar, se ela quiser.",
      'cha_c_16_extra': "Silêncio não é sinônimo de constrangimento, pode ser um sinal de conforto.",
      'cha_c_17_title': "Iniciando com uma Pergunta de Opinião",
      'cha_c_17_obj': "Começar uma conversa sobre um tópico neutro.",
      'cha_c_17_step1': "Escolha um tópico leve e de interesse geral (ex: um filme novo, uma série popular, uma notícia).",
